package cn.fuzhu.toolkit.modules;
import cn.fuzhu.toolkit.FuzhuToolkitPlugin; import cn.fuzhu.toolkit.module.AbstractModule; import org.bukkit.*; import org.bukkit.command.*; import org.bukkit.entity.Player; import org.bukkit.event.*; import org.bukkit.event.player.PlayerTeleportEvent; import java.util.*;
public class BackModule extends AbstractModule {private final Map<UUID,Location> last=new HashMap<>();private Listener listener;public BackModule(FuzhuToolkitPlugin p){super(p);config=p.moduleConfig(id());}public String id(){return "Back";}public String description(){return "/back 返回上次传送前位置";}public void enable(){super.enable();listener=new Listener(){@EventHandler public void tp(PlayerTeleportEvent e){if(e.getFrom().getWorld()!=null&&!e.getFrom().equals(e.getTo()))last.put(e.getPlayer().getUniqueId(),e.getFrom());}};plugin.getServer().getPluginManager().registerEvents(listener,plugin);}public void disable(){if(listener!=null)HandlerList.unregisterAll(listener);super.disable();}public boolean handle(CommandSender s,String l,String[] a){Player p=ModuleUtil.player(plugin,s);if(p==null)return true;Location x=last.get(p.getUniqueId());if(x==null)plugin.msg(s,"&e没有可返回的位置。");else{p.teleport(x);plugin.msg(s,"&a已返回上一位置。");}return true;}}
